<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue';
import { api, date, type Page } from '../lib/api';
import Icon from './Icon.vue';
import Pagination from './Pagination.vue';
const emit=defineEmits<{toast:[message:string];changed:[]}>();
type Settings={features:Record<string,boolean>;security:{registration_enabled:boolean;email_verification_enabled:boolean;email_domains:string[]};mail:{host:string;port:number;username:string;from_email:string;from_name:string;encryption:string;password_configured:boolean}};
type MailLog={id:string;recipient:string;purpose:string;status:string;attempts:number;error_code:string;created_at:string;sent_at:string|null};
const settings=ref<Settings>(),tab=ref('features'),loading=ref(true),busy=ref(false),testing=ref(false),error=ref('');
const domains=ref(''),password=ref(''),clearPassword=ref(false),recipient=ref(''),logs=ref<MailLog[]>([]),page=ref(1),total=ref(0),logError=ref('');
const features=[{key:'overview',label:'服务总览',note:'总览页面与统计查询'},{key:'refunds',label:'申请记录与提交',note:'网页与 API 的申请提交、查询及撤回；已受理任务继续执行'},{key:'billing',label:'资金与账单',note:'账单查询及兑换码入账'},{key:'developer',label:'接口接入',note:'API 密钥管理、开放 API 与接口手册'},{key:'announcements',label:'公告中心',note:'登录页、总览及公告列表'},{key:'help',label:'使用指南',note:'服务台的帮助页面'}];
const statusLabels:Record<string,string>={queued:'等待发送',sending:'发送中',retry:'等待重试',sent:'已发送',failed:'发送失败',expired:'已失效'};
const reasons:Record<string,string>={smtp_delivery_failed:'SMTP 发送失败，请检查配置或稍后重新获取验证码',expired_or_replaced:'已过期、已使用或设置已变更',superseded:'已被新验证码替代'};
let interval:ReturnType<typeof setInterval>;
async function load(){try{settings.value=await api<Settings>('/api/admin/site-settings');domains.value=settings.value.security.email_domains.join('\n')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function loadLogs(){try{const result=await api<Page<MailLog>>(`/api/admin/site-settings/mail/logs?page=${page.value}&size=20`);logs.value=result.items;total.value=result.total;logError.value=''}catch(e){logError.value=(e as Error).message}}
async function save(){
 if(!settings.value||busy.value)return;busy.value=true;error.value='';
 try{
  const value=tab.value==='features'?settings.value.features:tab.value==='security'?{...settings.value.security,email_domains:domains.value.split(/[\s,，;；]+/).filter(Boolean)}:{...settings.value.mail,password:password.value,clear_password:clearPassword.value};
  await api(`/api/admin/site-settings/${tab.value}`,{method:'PUT',body:JSON.stringify(value)});password.value='';clearPassword.value=false;await load();emit('toast','站点设置已保存');emit('changed');
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
async function test(send:boolean){
 if(testing.value)return;testing.value=true;error.value='';
 try{await api(`/api/admin/site-settings/mail/${send?'test':'connection'}`,{method:'POST',...(send?{body:JSON.stringify({email:recipient.value})}:{})});emit('toast',send?'测试邮件已加入发送队列':'SMTP 连接与认证成功');await loadLogs()}catch(e){error.value=(e as Error).message}finally{testing.value=false}
}
onMounted(()=>{load();loadLogs();interval=setInterval(()=>{if(tab.value==='mail'&&!document.hidden)loadLogs()},5000)});onUnmounted(()=>clearInterval(interval));
</script>
<template>
 <section class="site-settings">
  <header class="site-intro"><div><span class="eyebrow">SITE / PREFERENCES</span><h2>站点设置</h2><p>管理服务台功能、账户注册与邮件发送。</p></div><Icon name="Settings" :size="30"/></header>
  <nav class="site-sections" aria-label="站点设置分类"><button v-for="item in [{key:'features',label:'功能开关',icon:'LayoutDashboard'},{key:'security',label:'安全与认证',icon:'ShieldCheck'},{key:'mail',label:'邮件设置',icon:'Inbox'}]" :key="item.key" :class="{active:tab===item.key}" @click="tab=item.key;error=''"><Icon :name="item.icon" :size="17"/>{{item.label}}</button></nav>
  <p v-if="error" class="error-banner" role="alert">{{error}}</p><div v-if="loading" class="loading">正在加载站点设置…</div>
  <form v-else-if="settings" class="site-card" @submit.prevent="save">
   <template v-if="tab==='features'"><h3>前台功能</h3><p class="site-description">关闭后，该功能的菜单、页面模块和接口均不可访问。运营控制台按账户权限独立开放。</p><label v-for="item in features" :key="item.key" class="site-toggle"><span><strong>{{item.label}}</strong><small>{{item.note}}</small></span><input v-model="settings.features[item.key]" type="checkbox" role="switch" :aria-label="item.label"/></label></template>
   <template v-else-if="tab==='security'"><h3>安全与认证</h3><p class="site-description">注册策略由服务端校验，现有账户登录不受白名单调整影响。</p><label class="site-toggle"><span><strong>开放注册</strong><small>允许访客创建自己的服务账户</small></span><input v-model="settings.security.registration_enabled" type="checkbox" role="switch"/></label><label class="site-toggle"><span><strong>邮箱验证</strong><small>注册时必须填写邮箱验证码；开启前请先配置邮件服务</small></span><input v-model="settings.security.email_verification_enabled" type="checkbox" role="switch"/></label><label class="site-field">邮箱域名白名单<textarea v-model="domains" rows="5" placeholder="qq.com&#10;@gmail.com&#10;*.example.com"/><small>每行一个，也可用逗号分隔。留空允许所有域名；*.example.com 包含主域名及其子域名。仅限制新注册。</small></label><div class="site-note"><Icon name="LockKeyhole" :size="18"/><p>邮件配置可用后自动提供“忘记密码”。通过邮箱验证码重置密码后，旧登录会话及 API 密钥会失效。</p></div></template>
   <template v-else><h3>邮件发送服务</h3><p class="site-description">配置 SMTP，用于注册验证码、找回密码和测试邮件。密码留空保留已保存的授权密码。</p><div class="site-grid"><label class="site-field">SMTP 主机<input v-model="settings.mail.host" required maxlength="253" placeholder="smtp.example.com"/></label><label class="site-field">端口<input v-model.number="settings.mail.port" required type="number" min="1" max="65535"/></label><label class="site-field">加密方式<select v-model="settings.mail.encryption"><option value="starttls">STARTTLS（通常 587）</option><option value="tls">TLS（通常 465）</option><option value="none">无加密（仅免认证中继）</option></select></label><label class="site-field">SMTP 用户名<input v-model="settings.mail.username" maxlength="254" autocomplete="off" placeholder="邮箱账号或服务商用户名"/></label><label class="site-field">SMTP 授权密码<input v-model="password" type="password" autocomplete="new-password" maxlength="1024" :placeholder="settings.mail.password_configured?'已配置，留空保持':'填写 SMTP 授权密码'"/></label><label class="site-field">发件人邮箱<input v-model="settings.mail.from_email" required type="email" maxlength="254" placeholder="noreply@example.com"/></label><label class="site-field">发件人名称<input v-model="settings.mail.from_name" maxlength="80" placeholder="回序 HUIXU"/></label></div><label class="checkbox-label"><input v-model="clearPassword" type="checkbox"/>清除已保存密码（仅免认证中继适用）</label></template>
   <footer class="site-save"><span>仅管理员可以调整这些设置</span><button class="button primary" :disabled="busy">{{busy?'保存中…':'保存设置'}}</button></footer>
  </form>
  <template v-if="tab==='mail'&&settings"><section class="site-card"><h3>验证邮件配置</h3><p class="site-description">先保存配置，再测试。连接测试不发送邮件；发送测试需要填写收件邮箱。</p><div class="site-test"><button class="button secondary" :disabled="testing||busy" @click="test(false)">测试连接</button><form @submit.prevent="test(true)"><input v-model="recipient" aria-label="测试收件邮箱" type="email" required maxlength="254" placeholder="测试收件邮箱"/><button class="button secondary" :disabled="testing||busy">发送测试邮件</button></form></div></section><section class="table-card"><div class="table-toolbar"><h3>邮件发送记录</h3><button class="button secondary" @click="loadLogs"><Icon name="RefreshCw" :size="15"/>刷新记录</button></div><p v-if="logError" class="form-error">{{logError}}</p><div class="table-scroll"><table><thead><tr><th>收件邮箱</th><th>用途</th><th>状态</th><th>尝试次数</th><th>创建 / 发送时间</th><th>说明</th></tr></thead><tbody><tr v-for="row in logs" :key="row.id"><td>{{row.recipient}}</td><td>{{{register:'注册验证码',reset:'密码重置',test:'测试邮件'}[row.purpose]||row.purpose}}</td><td>{{statusLabels[row.status]||row.status}}</td><td>{{row.attempts}}</td><td>{{date(row.created_at)}}<br/><small v-if="row.sent_at">{{date(row.sent_at)}}</small></td><td>{{reasons[row.error_code]||'—'}}</td></tr><tr v-if="!logs.length"><td colspan="6" class="empty-state">暂无发送记录</td></tr></tbody></table></div><Pagination v-model:page="page" :total="total" :size="20" :sizes="[20]" @update:page="loadLogs"/><p class="site-log-note">记录保留 30 天，不展示验证码和邮件正文。发送失败最多尝试 3 次；验证码过期后需重新获取。</p></section></template>
 </section>
</template>
<style scoped>
.site-settings{display:grid;gap:20px;min-width:0}.site-intro{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:8px 0 4px}.site-intro h2{font-size:24px;margin:12px 0 8px}.site-intro p,.site-description{font-size:12px;color:var(--muted);line-height:1.8}.site-intro>svg{color:var(--accent)}.site-sections{display:flex;gap:8px;border-bottom:1px solid var(--line);overflow-x:auto}.site-sections button{display:flex;align-items:center;gap:9px;padding:13px 18px;white-space:nowrap;border-bottom:2px solid transparent;color:var(--muted);font-size:13px}.site-sections button.active{color:var(--accent);border-color:var(--accent);background:#ecefdf}.site-card{background:#fff;border:1px solid var(--line);border-radius:8px;padding:26px}.site-card h3{font-size:17px;margin-bottom:10px}.site-description{margin-bottom:20px}.site-toggle{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 0;border-top:1px solid var(--line)}.site-toggle span{display:grid;gap:7px}.site-toggle strong{font-size:13px;font-weight:600}.site-toggle small,.site-field small{font-size:11px;color:var(--muted);line-height:1.7}.site-toggle input{appearance:none;width:40px;height:23px;border-radius:20px;background:#c9cec1;position:relative;flex-shrink:0;padding:0;cursor:pointer;border:0}.site-toggle input:after{content:'';position:absolute;width:17px;height:17px;top:3px;left:3px;background:white;border-radius:50%;transition:transform .15s}.site-toggle input:checked{background:#6d8151}.site-toggle input:checked:after{transform:translateX(17px)}.site-toggle input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.site-field{display:grid;gap:9px;font-size:12px;margin:16px 0}.site-field input,.site-field select,.site-field textarea{width:100%;min-width:0;font-size:13px}.site-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.site-note{display:flex;gap:12px;background:#f2f3eb;padding:16px;border-radius:6px;color:var(--muted);font-size:12px;line-height:1.8}.site-note svg{flex-shrink:0;margin-top:3px}.site-save{display:flex;justify-content:space-between;align-items:center;gap:15px;border-top:1px solid var(--line);margin-top:22px;padding-top:20px}.site-save span,.site-log-note{font-size:11px;color:var(--muted)}.site-test,.site-test form{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.site-test input{min-width:180px;font-size:12px}.site-log-note{padding:16px 22px;line-height:1.7}.site-settings .table-toolbar{justify-content:space-between}.site-settings td{font-size:12px;overflow-wrap:anywhere}.site-settings .table-card{margin:0}.site-settings th{white-space:nowrap}@media(max-width:720px){.site-card{padding:20px}.site-grid{grid-template-columns:1fr}.site-save span{display:none}.site-save{justify-content:flex-end}.site-sections button{padding:12px}.site-test form,.site-test input{width:100%}}
</style>
